    private record Patient(Identity owner,double until){}
    private final Thread owner=Thread.currentThread();private final BotNavigationWorld world;private final RecoveryPlanning.World collision;private long map=-1,mode=-1;private final LinkedHashMap<Observer,Life> lives=new LinkedHashMap<>();private TeamTasks teams=new TeamTasks();private SchematicSites sites=new SchematicSites();private final LinkedHashMap<Identity,Patient> patients=new LinkedHashMap<>();
    public CooperativeBehavior(BotNavigationWorld world){this.world=world;collision=RecoveryPlanning.reader(world);}
    void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Cooperative behavior outside worker");}
    public TeamTasks teams(){owned();return teams;}public SchematicSites sites(){owned();return sites;}public int lifeCount(){owned();return lives.size();}
    public void reset(){owned();lives.clear();patients.clear();teams=new TeamTasks();if(map!=-1||mode!=-1)sites=new SchematicSites();}
    public void forget(int id,int generation){owned();var life=lives.remove(new Observer(id,generation));sites.forget(id,generation);if(life!=null){if(life.task!=null)teams.remove(life.task.id);patients.entrySet().removeIf(e->e.getKey().equals(life.key)||e.getValue().owner().equals(life.key));}}
    public static double mix(long... values){long acc=0x811c9dc5L;for(long v:values)acc=((acc^(v&0xffff_ffffL))*0x01000193)&0xffff_ffffL;return (acc%997)/997.;}
    static boolean landed(Player p,Vector at){return p.grounded()&&!p.wade()&&Math.floor(p.position().x())==Math.floor(at.x())&&Math.floor(p.position().y())==Math.floor(at.y())&&Math.abs(p.position().z()-at.z())<1;}
    static int stock(Player p,int tool){return p.deployableStock().stream().filter(s->s.tool()==tool).mapToInt(Stock::count).findFirst().orElse(0);}
    public static int ammunition(Player p){return p.weaponAmmo().isEmpty()?p.ammoClip()+p.ammoReserve():p.weaponAmmo().stream().mapToInt(a->a.clip()+a.reserve()).sum();}
    static Order order(long id,String role,Vector goal,Vector look,Action action,double radius,boolean hold,boolean urgent,int tool){return new Order(id,role,goal,look,action,radius,hold,urgent,tool);}
    static Order order(long id,String role,Vector goal,Vector look,double radius,boolean hold,int tool){return order(id,role,goal,look,Action.none(),radius,hold,false,tool);}
    static Order move(Task t,Vector goal,String role,double radius){return order(t.id,role,goal,t.lane,radius,false,-1);}
    static Action action(ActionKind kind,int tool,Vector at,Vector end,String argument,int face,double yaw,int burst,double pause){return new Action(kind,tool,at,end,argument,face,yaw,burst,pause,0);}
    static Action action(ActionKind kind,int tool,Vector at){return action(kind,tool,at,null,"",-1,0,0,0);}
    static boolean canStop(BotModeDecision strategic){return !strategic.role().endsWith("_passive")&&!Set.of("demolition_escape_airstrike","occupation_dispose_bomb","zombie_last_survivor_escape","vip_retreat","multihill_evade_airstrike").contains(strategic.role());}
    static boolean urgent(Task t,Player p){if(p.carriedEntityId()>=0)return false;return t.kind.equals("heal")&&!Objects.equals(t.patient,identity(p))||p.health()<40||ammunition(p)==0;}
