    static boolean continues(Task t,BotModeDecision s,double now){return ERRANDS.contains(t.kind)&&now<t.expiresAt&&canStop(s);}
    static boolean combatRelevant(Perception f,Player p,Player visible){if(visible==null)return false;if(p.lastDamageSourceId()==visible.id()&&BotModePolicies.hurt(f,p,2))return true;var choices=new ArrayList<Integer>();choices.add(p.weaponTool());choices.add(p.tool());choices.addAll(p.loadout().subList(0,Math.min(16,p.loadout().size())));Integer weapon=choices.stream().filter(t->p.loadout().contains(t)&&CombatCatalog.WEAPONS.containsKey(t)).findFirst().orElse(null);double range=weapon==null?10:Math.max(10,BotCombatProfiles.envelope(weapon).idealMax());return distance(p.eye(),visible.eye())<=range;}
    boolean affordsPrefab(Player p){return p.prefabs().stream().limit(3).anyMatch(name->{var g=world.prefabGeometry().get(name.toLowerCase(Locale.ROOT));return g!=null&&g.blockCount()>0&&g.blockCount()<=p.blocks();});}
    static boolean nearObjective(Perception f,Vector at,double radius){return f.objectives().stream().anyMatch(o->!o.kind().equals("zombie_refuge")&&distance(at,o.position())<radius);}
    static Vector refuge(Perception f,Player p){var o=BotModePolicies.objective(f,"zombie_refuge",p.team());return o==null?null:o.position();}
    static boolean hazard(Perception f,Player p){return f.entities().stream().limit(64).anyMatch(e->e.alive()&&e.hazardous()&&(e.team()==p.team()||e.kind().equals("projectile"))&&distance(e.position(),p.position())<e.blastRadius()+3);}
    static Vector facing(Vector p,Vector t){double x=t.x()-p.x(),y=t.y()-p.y(),len=Math.hypot(x,y);return len>1e-6?new Vector(x/len,y/len,0):new Vector(1,0,0);}
    static Vector fortifyLane(Perception f,Player p,BotModeDecision s){var threat=s.watchPosition();if(threat==null){var o=BotModePolicies.enemy(f,"team_anchor",p);if(o!=null)threat=o.position();}if(threat==null||flat(threat,p.position())<1e-6)return s.position();var h=facing(p.position(),threat);return new Vector(p.position().x()+h.x()*12,p.position().y()+h.y()*12,p.position().z());}
    Set<Cell> reserved(int team,long exclude){var cells=new HashSet<Cell>();for(var p:teams.projects().values())if(p.team==team&&p.id!=exclude)cells.addAll(p.cells);cells.addAll(sites.reserved(team,-1));return Set.copyOf(cells);}
    void expire(Perception f,double now){var observed=new LinkedHashMap<Observer,Observed>();var alive=new LinkedHashMap<Observer,Integer>();for(var p:f.players()){var key=new Observer(p.id(),p.generation());observed.put(key,new Observed(p.alive()&&p.spawned(),p.lifeId()));if(p.alive()&&p.spawned())alive.put(key,p.lifeId());}teams.expire(now,observed);sites.refresh(collision,now,alive);for(var e:new ArrayList<>(lives.entrySet())){var life=e.getValue();var o=observed.get(e.getKey());if(now-life.lastSeen>15||o!=null&&(!o.alive()||o.life()!=life.key.life()))forget(e.getKey().id(),e.getKey().generation());}while(lives.size()>128){var key=lives.entrySet().stream().min(Comparator.comparingDouble(e->e.getValue().lastSeen)).orElseThrow().getKey();forget(key.id(),key.generation());}patients.values().removeIf(p->p.until()<=now);}
