        if(task!=null&&task.kind.equals("schematic")&&task.pending==null&&BotModePolicies.hurt(f,p,1)){var site=sites.sites().get(task.schematicId);if(site!=null)sites.underFire(site,now);finish(life,now,false,"under_fire");life.nextProject=now+6;}task=life.task;if(task!=null&&(critical&&!support||danger&&!task.kind.equals("heal")&&!fetching||interrupt||hazard(f,p)))finish(life,now,false,interrupt?"combat_contact":"urgent_interrupt");task=life.task;if(task!=null&&Set.of("outpost","cover","strongpoint","sabotage").contains(task.kind)&&ammunition(p)<=0)finish(life,now,false,"ammo_exhausted");
        if(critical){life.partner=null;life.partnerAnchor=null;life.partnerHolding=false;life.partnerUntil=0;if(life.task!=null){var result=advance(f,p,contact,life,allies);if(result!=null||life.task!=null)return result;}if(building&&contact==null&&!hazard(f,p)){var sheltered=vipShelterHold(f,p,strategic);if(sheltered!=null)return sheltered;if(now>=life.nextProject){var work=schematicTask(f,p,life,strategic,allies,true,null);if(work!=null){life.task=work;teams.event("tasks_started",work.id,work.kind,now);return advance(f,p,contact,life,allies);}life.nextProject=now+4;}}
            boolean medic=p.loadout().contains(c("medpack_tool"))&&stock(p,c("medpack_tool"))>0;if(strategic!=null&&canStop(strategic)&&contact==null&&now>=life.nextEvaluate&&!hazard(f,p)&&(p.health()<55||ammunition(p)==0||medic)){life.nextEvaluate=now+.75;var work=medical(f,p,p.carriedEntityId()>=0||!medic?List.of(p):allies,life,14);if(work==null)work=recovery(f,p,life,allies);if(work!=null){if(worth(work,p,strategic)){if(!urgent(work,p))work.expiresAt=Math.min(work.expiresAt,now+4);life.task=work;teams.event("tasks_started",work.id,work.kind,now);return advance(f,p,contact,life,allies);}if(work.patient!=null){var claim=patients.get(work.patient);if(claim!=null&&claim.owner().equals(life.key))patients.remove(work.patient);}}}return null;}
        if(life.task!=null){var result=advance(f,p,contact,life,allies);if(result!=null)return result;}if(now<life.nextEvaluate){var order=life.task==null?supportProject(f,p,contact):null;return order!=null?order:partner(f,p,life,allies,contact);}life.nextEvaluate=now+.5+Math.floorMod(p.id(),7)*.027;if(life.task==null){var healing=medical(f,p,allies,life,24);if(healing!=null){life.task=healing;teams.event("tasks_started",healing.id,healing.kind,now);return advance(f,p,contact,life,allies);}}if(life.task!=null)return null;if(contact!=null||hazard(f,p)){if(ammunition(p)<=0&&!hazard(f,p)){var supply=supply(f,p,life);if(supply!=null){life.task=supply;teams.event("tasks_started",supply.id,supply.kind,now);return advance(f,p,contact,life,allies);}}return null;}
        var remembered=life.memory.contact(p.position(),now);Vector lane=visible!=null?visible.eye():remembered!=null?remembered.position():strategic==null?null:strategic.position();if(fortifying&&visible==null&&remembered==null)lane=fortifyLane(f,p,strategic);double creativity=f.profile()==null?.5:f.profile().creativity(),teamwork=f.profile()==null?.5:f.profile().teamwork();var candidates=new ArrayList<Task>();long id=f.frameId()*256+p.id();if(contact==null){var recovery=recovery(f,p,life,allies);if(recovery!=null)candidates.add(recovery);var sabotage=sabotage(f,p,life,allies);if(sabotage!=null)candidates.add(sabotage);}var friends=allies.stream().filter(q->q.id()!=p.id()).map(Player::position).toList();var reserved=reserved(p.team(),-1);
        if(lane!=null&&now>=life.nextProject&&p.health()>=45){boolean sniper=p.loadout().contains(c("sniper_tool"))||p.loadout().contains(c("sniper2_tool")),miner=p.loadout().contains(c("superspade_tool"));Site site=null;String kind="";var refuge=fortifying?refuge(f,p):null;if(refuge!=null&&p.loadout().contains(c("block_tool"))&&distance(p.position(),refuge)<=14){site=ProjectSites.rampart(world,p,refuge,friends,reserved,4,2);kind="rampart";}if(site==null){if(sniper&&distance(p.position(),lane)>18){site=ProjectSites.sniper(world,p,lane,friends,Set.of());kind="outpost";}else if(miner&&contact==null&&!(Math.floorMod(p.id()+(int)(now/4),3)==0&&affordsPrefab(p))){site=ProjectSites.bridge(world,p,lane,reserved);kind="bridge";if(site==null){site=ProjectSites.breach(world,p,lane,Set.of());kind="breach";}}else if(p.blocks()>=6&&(contact==null||p.reloading())&&(creativity>.35||fortifying)){site=ProjectSites.cover(world,p,lane,false,friends,reserved);kind=p.loadout().contains(c("rocket_turret_tool"))?"strongpoint":"cover";}}if(site!=null&&(kind.equals("rampart")||!nearObjective(f,site.position(),10))){double score=kind.equals("rampart")?.8+teamwork*.1:.66+creativity*.18+teamwork*.08;score-=life.memory.penalty(kind,site.position(),now);if(score>.35){double patience=24+48*(f.profile()==null?.5:f.profile().caution());var t=new Task(id,kind,site.approach(),lane,now,now+(kind.equals("outpost")?patience:25),score);t.site=site;candidates.add(t);}}}
        if(visible==null&&remembered!=null&&remembered.expiresAt()-now>=2&&distance(p.position(),remembered.position())>4){double score=.4+creativity*.1-life.memory.penalty("investigate",remembered.position(),now);if(score>.2)candidates.add(new Task(id,"investigate",remembered.position(),remembered.position(),now,Math.min(remembered.expiresAt(),now+6),score));}if(visible==null&&now>=life.nextProject&&p.health()>=45&&!fortifying){var schematic=schematicTask(f,p,life,strategic,allies,false,lane);if(schematic!=null)candidates.add(schematic);}if(!candidates.isEmpty()){var chosen=candidates.subList(0,Math.min(4,candidates.size())).stream().max(Comparator.comparingDouble(t->t.score+Math.floorMod(id*17+t.kind.length()*31,19)*.001)).orElseThrow();if(chosen.site==null||teams.reserve(new Project(chosen.id,p.team(),chosen.kind,identity(p),chosen.site.approach(),chosen.lane,now,chosen.expiresAt,chosen.site.cells(),now))){life.task=chosen;life.nextProject=now+3;teams.event("tasks_started",chosen.id,chosen.kind,now);return advance(f,p,contact,life,allies);}}
        var helping=supportProject(f,p,contact);if(helping!=null)return helping;var partner=partner(f,p,life,allies,contact);if(partner!=null)return partner;if(f.friendlyMischief()&&f.localSafetyComplete()&&visible==null&&remembered==null&&life.memory.snapshot().pressure()<.1&&p.blocks()>=30&&allies.stream().anyMatch(q->q.id()!=p.id()&&distance(q.position(),p.position())<18)&&creativity>.6&&now>=teams.mischiefReady(p.team())&&Math.floorMod((int)(now+p.id()*13),47)==0&&!nearObjective(f,p.position(),24)){var site=ProjectSites.decoration(world,p,friends,reserved);if(site!=null&&teams.allowMutation(p.team(),now,1)){teams.mischiefReady(p.team(),now+90);life.task=new Task(id,"mischief",site.approach(),site.position(),now,now+8,.1);life.task.site=site;teams.event("tasks_started",id,"mischief",now);return advance(f,p,visible,life,allies);}}return null;
